StructuredTextModel.Text:
(* Determine the direction to feed based on the signal, adjust the distance *)
IF Fwd_Sig THEN
	Signed_Distance := Distance;
ELSIF Rev_Sig THEN
	Signed_Distance := Distance*-1;
END_IF;

(* Convert or not from metric to imperial and output the correct unit string *)
IF (NOT Unit) THEN
	Distance_O := Adj_Feed(Signed_Distance*25.4, Adj_Fac);
	Speed_O := Speed*25.4;
	Unit_Str := 'in';
ELSE
	Distance_O := Adj_Feed(Signed_Distance, Adj_Fac);
	Speed_O := Speed;
	Unit_Str := 'mm';
END_IF;

Accel_O := Percent_Limit(Limits.Min_Accel, Limits.Max_Accel, Accel);
Decel_O := Percent_Limit(Limits.Min_Decel, Limits.Max_Decel, Decel);

// Limit the maximum speed to two inches per second in manual mode
IF (NOT Micro_Mode) THEN
	IF (Manual_Speed_C < Manual_Limit) THEN
		Speed_O := Manual_Speed_C;
	ELSE
		Speed_O := Manual_Limit;
	END_IF;
ELSE
	// Limit the speed further when in micro
	IF (Manual_Speed_C < Manual_Limit_Micro) THEN
		Speed_O := Manual_Speed_C;
	ELSE
		Speed_O := Manual_Limit_Micro;
	END_IF;
END_IF;
